// GENERATED by scripts/build-voice-pack.mjs from scripts/talk-phrases.json. Do not edit.

export const voiceKey = (text) => {
  let h = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i)
    h = Math.imul(h, 0x01000193)
  }
  return (h >>> 0).toString(16).padStart(8, '0')
}

// What is actually said for a label: English helper notes in brackets are for
// sighted/dev readers and are dropped, as are keyboard shortcuts (Alt+2), links and extra whitespace.
export const spokenForm = (text) =>
  String(text || '')
    .replace(/\s*\((?=[^()]*[A-Za-z])[^()]*\)/g, '')
    .replace(/https?:\/\/\S+/g, '')
    .replace(/\s*\b(?:Alt|Ctrl|Shift)\+\S+/g, '')
    .replace(/\s+/g, ' ')
    .trim()

